contract.content:
{
  "action": "execute",
  "archetype": "dashboard",
  "message": "A unified KPI dashboard pulling live pipeline and renewals data from Snowflake using canonical metric definitions. Admins (Finance/Sales/Ops leads) manage shared definitions like 'active customer' in a dedicated admin area, with every change recorded in an audit log so leadership can trace why numbers moved. Executives and regional managers see the same trusted numbers, can export views to CSV, and review definition history.",
  "flags": ["has-users", "has-admin", "snowflake", "exports-csv"],
  "tasks": [
    {
      "scope": "database",
      "summary": "Stores users, canonical metric definitions, and the audit trail of every definition change.",
      "task": "Tables: users, metric_definitions, definition_change_logs. Indexes: metric_definitions(key), definition_change_logs(metric_definition_id, changed_at DESC), users(oidc_sub). Column-level contract: data_model.",
      "dockerfile": "Dockerfile.postgres",
      "rules": [],
      "snippets": [],
      "primarySnippet": null
    },
    {
      "scope": "backend",
      "summary": "Serves dashboard KPIs from Snowflake using canonical definitions, manages admin edits, and records audit history.",
      "task": "Data: pg Pool from env; Snowflake client from env (SNOWFLAKE_ACCOUNT/USER/PASSWORD/WAREHOUSE/DATABASE/SCHEMA). Endpoints + bodies: api_contract. Behaviors + rules + side-effects: business_logic_contract. Auth: x-amzn-oidc-data JWT (sub, email). Role resolution from users.role. Snowflake queries built dynamically from metric_definitions.sql_expression. CSV export streams from /metrics/:key/export.",
      "dockerfile": "Dockerfile.node",
      "rules": [],
      "snippets": [],
      "primarySnippet": "backend/express-server-template.ts"
    },
    {
      "scope": "frontend",
      "summary": "Single dashboard view of pipeline and renewal KPIs, plus an admin area for managing definitions and reviewing change history.",
      "task": "Views + components: ui_contract. Endpoints + body shapes: api_contract (prepend /api/). Admin routes guarded by role from /whoami. States: spinner, empty CTA, toast on 4xx/5xx, 404 page, disabled submit during POST. Responsive.",
      "dockerfile": "Dockerfile.react",
      "rules": [],
      "snippets": [],
      "primarySnippet": "frontend/AppScaffold.tsx"
    },
    {
      "scope": "integration",
      "summary": "Wires the dashboard, API, and database together for local development with Snowflake credentials passed through.",
      "task": "Wire database, backend, frontend. Backend env: DATABASE_HOST=database, DATABASE_PORT=5432, DATABASE_NAME=kpi_dashboard, DATABASE_USER=kpi_dashboard_user, DATABASE_PASSWORD=localdev123, SNOWFLAKE_ACCOUNT, SNOWFLAKE_USER, SNOWFLAKE_PASSWORD, SNOWFLAKE_WAREHOUSE, SNOWFLAKE_DATABASE, SNOWFLAKE_SCHEMA. nginx.local.conf proxy /api→backend:3000. depends_on chain. Healthchecks. Volumes per service.",
      "dockerfile": null,
      "rules": [],
      "snippets": [],
      "primarySnippet": "integration/docker-compose-fullstack.yml"
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "users",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "oidc_sub", "type": "TEXT UNIQUE NOT NULL"},
          {"name": "email", "type": "VARCHAR(255) NOT NULL"},
          {"name": "name", "type": "VARCHAR(255)"},
          {"name": "role", "type": "VARCHAR(64) NOT NULL DEFAULT 'viewer'"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "metric_definitions",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "key", "type": "VARCHAR(128) UNIQUE NOT NULL"},
          {"name": "label", "type": "VARCHAR(255) NOT NULL"},
          {"name": "category", "type": "VARCHAR(64) NOT NULL"},
          {"name": "description", "type": "TEXT NOT NULL"},
          {"name": "sql_expression", "type": "TEXT NOT NULL"},
          {"name": "unit", "type": "VARCHAR(32)"},
          {"name": "version", "type": "INTEGER NOT NULL DEFAULT 1"},
          {"name": "updated_by_user_id", "type": "INTEGER REFERENCES users(id)"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"},
          {"name": "updated_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "definition_change_logs",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "metric_definition_id", "type": "INTEGER NOT NULL REFERENCES metric_definitions(id) ON DELETE CASCADE"},
          {"name": "changed_by_user_id", "type": "INTEGER REFERENCES users(id)"},
          {"name": "change_type", "type": "VARCHAR(32) NOT NULL"},
          {"name": "previous_value", "type": "JSONB"},
          {"name": "new_value", "type": "JSONB NOT NULL"},
          {"name": "change_note", "type": "TEXT"},
          {"name": "changed_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      }
    ]
  },
  "api_contract": {
    "version": 1,
    "endpoints": [
      {
        "method": "GET",
        "path": "/whoami",
        "response": {"status": 200, "body": "{ id, email, name, role }"}
      },
      {
        "method": "GET",
        "path": "/dashboard/pipeline",
        "response": {"status": 200, "body": "{ metrics: [{ key, label, value, unit, as_of }] }"}
      },
      {
        "method": "GET",
        "path": "/dashboard/renewals",
        "response": {"status": 200, "body": "{ metrics: [{ key, label, value, unit, as_of }] }"}
      },
      {
        "method": "GET",
        "path": "/metrics/:key/export",
        "response": {"status": 200, "body": "text/csv stream"}
      },
      {
        "method": "GET",
        "path": "/metric-definitions",
        "response": {"status": 200, "body": "{ items: [{ id, key, label, category, description, unit, version, updated_at }] }"}
      },
      {
        "method": "GET",
        "path": "/metric-definitions/:id",
        "response": {"status": 200, "body": "{ id, key, label, category, description, sql_expression, unit, version, updated_at }"}
      },
      {
        "method": "POST",
        "path": "/metric-definitions",
        "request": "{ key: string required, label: string required, category: string required, description: string required, sql_expression: string required, unit?: string, change_note?: string }",
        "response": {"status": 201, "body": "{ id, key, label, category, version }"}
      },
      {
        "method": "PUT",
        "path": "/metric-definitions/:id",
        "request": "{ label?: string, category?: string, description?: string, sql_expression?: string, unit?: string, change_note?: string }",
        "response": {"status": 200, "body": "{ id, key, label, version }"}
      },
      {
        "method": "DELETE",
        "path": "/metric-definitions/:id",
        "request": "{ change_note?: string }",
        "response": {"status": 204, "body": ""}
      },
      {
        "method": "GET",
        "path": "/metric-definitions/:id/history",
        "response": {"status": 200, "body": "{ items: [{ id, change_type, previous_value, new_value, change_note, changed_by: { email, name }, changed_at }], limit, offset }"}
      },
      {
        "method": "GET",
        "path": "/audit-log",
        "response": {"status": 200, "body": "{ items: [{ id, metric_definition_id, metric_key, change_type, change_note, changed_by: { email, name }, changed_at }], limit, offset }"}
      }
    ]
  },
  "ui_contract": {
    "primary_view": "unified KPI dashboard of pipeline and renewals",
    "primary_action": "view trusted KPI values backed by canonical definitions",
    "secondary_views": [
      "admin metric definitions list",
      "metric definition editor",
      "definition change history",
      "global audit log"
    ],
    "components": [
      {"name": "DashboardLayout", "role": "top-level shell with role-aware nav"},
      {"name": "KpiSection", "role": "groups KPI cards by category (pipeline, renewals)"},
      {"name": "KpiCard", "role": "single KPI value with label, unit, as-of timestamp, and link to its definition"},
      {"name": "DefinitionTooltip", "role": "inline preview of canonical definition for a KPI"},
      {"name": "ExportCsvButton", "role": "triggers CSV download for a metric or dashboard section"},
      {"name": "AdminDefinitionsTable", "role": "admin list of all metric definitions with edit/delete"},
      {"name": "DefinitionEditorForm", "role": "form for creating/editing a metric definition with SQL expression and change note"},
      {"name": "DefinitionHistoryPanel", "role": "chronological diff view of changes to a single definition"},
      {"name": "AuditLogTable", "role": "global view of all definition changes with who/what/when"},
      {"name": "RoleGuard", "role": "hides admin routes from non-admin users"},
      {"name": "EmptyState", "role": "shown when Snowflake returns no rows or definitions list is empty"},
      {"name": "ErrorToast", "role": "displays API errors uniformly"}
    ]
  },
  "business_logic_contract": {
    "triggers": [
      {"event": "user_first_login", "action": "create users row from x-amzn-oidc-data claims (sub, email); default role='viewer'"},
      {"event": "dashboard_view_requested", "action": "load active metric_definitions for the category, execute their sql_expression against Snowflake, return aggregated values with as_of timestamp"},
      {"event": "metric_definition_created", "action": "insert metric_definitions row and write definition_change_logs entry with change_type='create' and new_value snapshot"},
      {"event": "metric_definition_updated", "action": "increment version, update row, write definition_change_logs entry with change_type='update', previous_value and new_value snapshots, and change_note"},
      {"event": "metric_definition_deleted", "action": "delete row and write definition_change_logs entry with change_type='delete' and previous_value snapshot"},
      {"event": "csv_export_requested", "action": "stream current metric values (or definition list) as text/csv with content-disposition attachment"}
    ],
    "rules": [
      "All authenticated users (executives, regional_sales_managers, finance_leads, sales_leads, operations_leads) can read /dashboard/* and /metric-definitions (read-only) and /audit-log",
      "Only users with role='admin' (Finance/Sales/Ops leads designated as admins) can POST/PUT/DELETE /metric-definitions/*",
      "metric_definitions.key is immutable after creation",
      "Every write to metric_definitions MUST produce a corresponding definition_change_logs row in the same transaction",
      "sql_expression must be validated against a Snowflake dry-run (EXPLAIN) before save; reject with 400 on parse error",
      "/whoami required for all routes except health; missing/invalid x-amzn-oidc-data returns 401",
      "List endpoints support ?limit=50&offset=0 and return newest-first"
    ],
    "side_effects": [
      "audit log on every metric_definition create/update/delete (write to definition_change_logs)",
      "Snowflake query executed on each dashboard load (cache optional, not required)"
    ]
  },
  "mga_assistants": []
}
